practice.solution:
@page "/weather"
@rendermode InteractiveServer
@implements IDisposable
@inject WeatherService Weather
@inject PersistentComponentState AppState

@if (forecasts is null)
{
    <p>Loading...</p>
}
else
{
    <p>@forecasts.Length days</p>
}

@code {
    private WeatherForecast[]? forecasts;
    private PersistingComponentStateSubscription subscription;

    protected override async Task OnInitializedAsync()
    {
        subscription = AppState.RegisterOnPersisting(Persist);

        if (!AppState.TryTakeFromJson<WeatherForecast[]>("forecasts", out var saved))
        {
            forecasts = await Weather.GetForecastsAsync();
        }
        else
        {
            forecasts = saved;
        }
    }

    private Task Persist()
    {
        AppState.PersistAsJson("forecasts", forecasts);
        return Task.CompletedTask;
    }

    public void Dispose() => subscription.Dispose();
}
